     1→import Phaser from 'phaser';
     2→import { BattleChannel } from '../utils/battleChannel';
     3→import { BattleEvent } from '../types/BattleTypes';
     4→import { getSafeSelectedCharacter } from '../utils/character';
     5→import { supabase } from '../utils/supabase';
     6→import BaseScene from './BaseScene';
     7→
     8→/**
     9→ * 대전 매칭 씬 — 상태별 UI 전환
    10→ *
    11→ * 상태: MENU → CREATE_WAITING / JOIN_INPUT → JOIN_WAITING → COUNTDOWN → BATTLE
    12→ */
    13→export default class BattleMatchScene extends BaseScene {
    14→  private battleChannel: BattleChannel | null = null;
    15→  private inputElement: HTMLInputElement | null = null;
    16→  private isHost: boolean = false;
    17→  private myReady: boolean = false;
    18→  private opponentReady: boolean = false;
    19→  private countdownStarted: boolean = false;
    20→  private readyRetryTimer: ReturnType<typeof setInterval> | null = null;
    21→  private userId: string = '';
    22→
    23→  // 상태별 UI 요소를 그룹으로 관리 → 상태 전환 시 일괄 파괴
    24→  private uiGroup: Phaser.GameObjects.GameObject[] = [];
    25→  private uiTimers: Phaser.Time.TimerEvent[] = [];
    26→
    27→  constructor() {
    28→    super('BattleMatchScene');
    29→  }
    30→
    31→  preload() {
    32→    if (!this.textures.exists('background2')) {
    33→      this.load.image('background2', 'assets/backgrounds/background2.webp');
    34→    }
    35→  }
    36→
    37→  create() {
    38→    super.create();
    39→
    40→    // 배경 (모든 상태에서 유지)
    41→    const bg = this.add.image(200, 300, 'background2');
    42→    bg.setDisplaySize(400, 600);
    43→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.6);
    44→
    45→    // 타이틀 (모든 상태에서 유지)
    46→    this.add.text(200, 60, '⚔️ 대전 모드', {
    47→      fontSize: '32px',
    48→      color: '#ff4444',
    49→      fontStyle: 'bold',
    50→      stroke: '#000',
    51→      strokeThickness: 5,
    52→    }).setOrigin(0.5);
    53→
    54→    this.add.text(200, 105, 'EXTREME 난이도로 1대1 대전!', {
    55→      fontSize: '14px',
    56→      color: '#cccccc',
    57→      stroke: '#000',
    58→      strokeThickness: 3,
    59→    }).setOrigin(0.5);
    60→
    61→    // 뒤로가기 (모든 상태에서 유지)
    62→    const backBtn = this.add.text(200, 560, '← 메인 메뉴', {
    63→      fontSize: '18px',
    64→      color: '#aaaaaa',
    65→      stroke: '#000',
    66→      strokeThickness: 3,
    67→    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    68→    backBtn.on('pointerover', () => backBtn.setColor('#ffffff'));
    69→    backBtn.on('pointerout', () => backBtn.setColor('#aaaaaa'));
    70→    backBtn.on('pointerdown', () => this.goBack());
    71→
    72→    // 유저 ID: 즉시 임시값 사용 → 백그라운드에서 실제 ID로 교체
    73→    // (Phaser는 async create()를 await하지 않으므로 동기 처리)
    74→    this.userId = `anon-${Date.now()}`;
    75→    supabase.auth.getUser().then(({ data }) => {
    76→      if (data.user?.id) this.userId = data.user.id;
    77→    });
    78→
    79→    // 초기 상태: 메뉴
    80→    this.showMenu();
    81→  }
    82→
    83→  /** 현재 상태의 UI 요소 일괄 파괴 */
    84→  private clearUI() {
    85→    this.removeInput();
    86→    for (const obj of this.uiGroup) {
    87→      if (obj.active) obj.destroy();
    88→    }
    89→    this.uiGroup = [];
    90→    // TimerEvent는 GameObject가 아니므로 별도 정리
    91→    for (const timer of this.uiTimers) {
    92→      timer.remove();
    93→    }
    94→    this.uiTimers = [];
    95→  }
    96→
    97→  /** UI 요소를 그룹에 추가 (나중에 일괄 파괴용) */
    98→  private ui<T extends Phaser.GameObjects.GameObject>(obj: T): T {
    99→    this.uiGroup.push(obj);
   100→    return obj;
   101→  }
   102→
   103→  // ─── 상태 1: 메뉴 (방 만들기 / 방 참가 선택) ─────────────────────
   104→
   105→  private showMenu() {
   106→    this.clearUI();
   107→
   108→    // 방 만들기 버튼
   109→    const createBtn = this.ui(this.add.rectangle(200, 250, 260, 70, 0xe74c3c));
   110→    createBtn.setStrokeStyle(3, 0xffffff);
   111→    this.ui(this.add.text(200, 250, '🏠 방 만들기', {
   112→      fontSize: '22px', color: '#ffffff', fontStyle: 'bold',
   113→    }).setOrigin(0.5));
   114→    createBtn.setInteractive({ useHandCursor: true });
   115→    createBtn.on('pointerover', () => createBtn.setAlpha(0.8));
   116→    createBtn.on('pointerout', () => createBtn.setAlpha(1));
   117→    createBtn.on('pointerdown', () => this.handleCreateRoom());
   118→
   119→    // 방 참가 버튼
   120→    const joinBtn = this.ui(this.add.rectangle(200, 350, 260, 70, 0x3498db));
   121→    joinBtn.setStrokeStyle(3, 0xffffff);
   122→    this.ui(this.add.text(200, 350, '🔗 방 참가', {
   123→      fontSize: '22px', color: '#ffffff', fontStyle: 'bold',
   124→    }).setOrigin(0.5));
   125→    joinBtn.setInteractive({ useHandCursor: true });
   126→    joinBtn.on('pointerover', () => joinBtn.setAlpha(0.8));
   127→    joinBtn.on('pointerout', () => joinBtn.setAlpha(1));
   128→    joinBtn.on('pointerdown', () => this.showJoinInput());
   129→
   130→    // 전적 보기 링크
   131→    const rankLink = this.ui(this.add.text(200, 450, '🏆 전적 보기', {
   132→      fontSize: '16px', color: '#aaaaaa',
   133→      stroke: '#000', strokeThickness: 3,
   134→    }).setOrigin(0.5).setInteractive({ useHandCursor: true }));
   135→    rankLink.on('pointerover', () => (rankLink as Phaser.GameObjects.Text).setColor('#FFD700'));
   136→    rankLink.on('pointerout', () => (rankLink as Phaser.GameObjects.Text).setColor('#aaaaaa'));
   137→    rankLink.on('pointerdown', () => this.scene.start('BattleLeaderboardScene'));
   138→  }
   139→
   140→  // ─── 상태 2a: 방 생성 대기 ─────────────────────────────────────
   141→
   142→  private async handleCreateRoom() {
   143→    if (this.battleChannel) return;
   144→    this.isHost = true;
   145→    this.myReady = false;
   146→    this.opponentReady = false;
   147→    this.countdownStarted = false;
   148→
   149→    const code = BattleChannel.generateRoomCode();
   150→    this.battleChannel = new BattleChannel();
   151→    this.battleChannel.createRoom(code, this.userId);
   152→    this.setupChannelListeners();
   153→    await this.battleChannel.subscribe();
   154→
   155→    this.showCreateWaiting(code);
   156→  }
   157→
   158→  private showCreateWaiting(code: string) {
   159→    this.clearUI();
   160→
   161→    this.ui(this.add.text(200, 200, '초대 코드', {
   162→      fontSize: '16px', color: '#aaaaaa',
   163→      stroke: '#000', strokeThickness: 3,
   164→    }).setOrigin(0.5));
   165→
   166→    this.ui(this.add.text(200, 260, code, {
   167→      fontSize: '56px', color: '#FFD700', fontStyle: 'bold',
   168→      stroke: '#000', strokeThickness: 6, letterSpacing: 10,
   169→    }).setOrigin(0.5));
   170→
   171→    this.ui(this.add.text(200, 330, '상대방에게 코드를 알려주세요', {
   172→      fontSize: '15px', color: '#ffffff',
   173→      stroke: '#000', strokeThickness: 3,
   174→    }).setOrigin(0.5));
   175→
   176→    // 대기 애니메이션 점
   177→    const dots = this.ui(this.add.text(200, 370, '대기 중', {
   178→      fontSize: '16px', color: '#888888',
   179→      stroke: '#000', strokeThickness: 3,
   180→    }).setOrigin(0.5));
   181→
   182→    let dotCount = 0;
   183→    this.uiTimers.push(
   184→      this.time.addEvent({
   185→        delay: 500,
   186→        loop: true,
   187→        callback: () => {
   188→          dotCount = (dotCount + 1) % 4;
   189→          if (dots.active) dots.setText('대기 중' + '.'.repeat(dotCount));
   190→        },
   191→      })
   192→    );
   193→  }
   194→
   195→  // ─── 상태 2b: 코드 입력 (방 참가) ──────────────────────────────
   196→
   197→  private showJoinInput() {
   198→    this.clearUI();
   199→
   200→    this.ui(this.add.text(200, 200, '방 코드 입력', {
   201→      fontSize: '18px', color: '#ffffff', fontStyle: 'bold',
   202→      stroke: '#000', strokeThickness: 3,
   203→    }).setOrigin(0.5));
   204→
   205→    // Phaser 캔버스 좌표 → DOM 좌표 변환
   206→    const canvas = this.game.canvas;
   207→    const rect = canvas.getBoundingClientRect();
   208→    const scaleX = rect.width / 400;
   209→    const scaleY = rect.height / 600;
   210→
   211→    const input = document.createElement('input');
   212→    input.type = 'text';
   213→    input.maxLength = 4;
   214→    input.placeholder = 'CODE';
   215→    input.style.cssText = `
   216→      position: fixed;
   217→      left: ${rect.left + 200 * scaleX}px;
   218→      top: ${rect.top + 270 * scaleY}px;
   219→      transform: translateX(-50%);
   220→      width: ${Math.round(200 * scaleX)}px;
   221→      height: ${Math.round(55 * scaleY)}px;
   222→      font-size: ${Math.round(30 * scaleY)}px;
   223→      text-align: center;
   224→      text-transform: uppercase;
   225→      border: 3px solid #FFD700;
   226→      border-radius: 12px;
   227→      background: #1a1a2e;
   228→      color: #FFD700;
   229→      font-weight: bold;
   230→      letter-spacing: ${Math.round(10 * scaleX)}px;
   231→      outline: none;
   232→      z-index: 9999;
   233→    `;
   234→    document.body.appendChild(input);
   235→    input.focus();
   236→    this.inputElement = input;
   237→
   238→    input.addEventListener('input', () => {
   239→      input.value = input.value.toUpperCase().replace(/[^A-Z0-9]/g, '');
   240→    });
   241→
   242→    // 에러 메시지 영역
   243→    const errorText = this.ui(this.add.text(200, 330, '', {
   244→      fontSize: '14px', color: '#ff4444',
   245→      stroke: '#000', strokeThickness: 3,
   246→    }).setOrigin(0.5));
   247→
   248→    // 참가 버튼
   249→    const joinBtn = this.ui(this.add.rectangle(200, 390, 200, 55, 0x27ae60));
   250→    joinBtn.setStrokeStyle(3, 0xffffff);
   251→    this.ui(this.add.text(200, 390, '참가', {
   252→      fontSize: '22px', color: '#ffffff', fontStyle: 'bold',
   253→    }).setOrigin(0.5));
   254→    joinBtn.setInteractive({ useHandCursor: true });
   255→    joinBtn.on('pointerover', () => joinBtn.setAlpha(0.8));
   256→    joinBtn.on('pointerout', () => joinBtn.setAlpha(1));
   257→
   258→    const doJoin = async () => {
   259→      const code = input.value.trim().toUpperCase();
   260→      if (code.length !== 4) {
   261→        errorText.setText('4자리 코드를 입력하세요');
   262→        return;
   263→      }
   264→
   265→      errorText.setText('');
   266→      this.isHost = false;
   267→      this.myReady = false;
   268→      this.opponentReady = false;
   269→      this.countdownStarted = false;
   270→      this.battleChannel = new BattleChannel();
   271→      this.battleChannel.joinRoom(code, this.userId);
   272→      this.setupChannelListeners();
   273→      await this.battleChannel.subscribe();
   274→
   275→      this.showJoinWaiting(code);
   276→    };
   277→
   278→    joinBtn.on('pointerdown', doJoin);
   279→    input.addEventListener('keypress', (e) => {
   280→      if (e.key === 'Enter') doJoin();
   281→    });
   282→
   283→    // 뒤로 (메뉴로)
   284→    const backText = this.ui(this.add.text(200, 470, '← 돌아가기', {
   285→      fontSize: '16px', color: '#888888',
   286→      stroke: '#000', strokeThickness: 3,
   287→    }).setOrigin(0.5).setInteractive({ useHandCursor: true }));
   288→    backText.on('pointerover', () => backText.setColor('#ffffff'));
   289→    backText.on('pointerout', () => backText.setColor('#888888'));
   290→    backText.on('pointerdown', () => this.showMenu());
   291→  }
   292→
   293→  // ─── 상태 3: 참가 후 대기 ──────────────────────────────────────
   294→
   295→  private showJoinWaiting(_code: string) {
   296→    // 구독 완료 → 즉시 ready 전송
   297→    this.doSendReady();
   298→  }
   299→
   300→  // ─── 채널 이벤트 ───────────────────────────────────────────────
   301→
   302→  private setupChannelListeners() {
   303→    if (!this.battleChannel) return;
   304→
   305→    // Presence join — 호스트일 때 상대 입장 UI 갱신 + 즉시 ready 전송
   306→    this.battleChannel.onPresenceJoin(() => {
   307→      if (this.isHost && !this.myReady) {
   308→        this.doSendReady();
   309→      }
   310→    });
   311→
   312→    this.battleChannel.onPresenceLeave(() => {
   313→      this.opponentReady = false;
   314→      this.ui(this.add.text(200, 420, '⚠️ 상대방이 나갔습니다', {
   315→        fontSize: '16px', color: '#ff4444',
   316→        stroke: '#000', strokeThickness: 3,
   317→      }).setOrigin(0.5));
   318→    });
   319→
   320→    // READY 수신 = 상대가 확실히 존재 + 준비 완료
   321→    // Presence join보다 READY가 먼저 올 수 있으므로, 여기서도 자신의 ready를 보냄
   322→    this.battleChannel.onEvent(BattleEvent.READY, () => {
   323→      this.opponentReady = true;
   324→      // 아직 내 ready를 안 보냈으면 즉시 보냄 (Presence 이벤트 누락 대비)
   325→      if (!this.myReady) {
   326→        this.doSendReady();
   327→      }
   328→      this.checkBothReady();
   329→    });
   330→
   331→    this.battleChannel.onEvent(BattleEvent.GAME_START, () => {
   332→      if (!this.countdownStarted) {
   333→        this.countdownStarted = true;
   334→        this.showCountdown();
   335→      }
   336→    });
   337→  }
   338→
   339→  /** ready 전송 (UI 상태와 분리 — 어디서든 호출 가능) */
   340→  private doSendReady() {
   341→    if (!this.battleChannel || this.myReady) return;
   342→    this.myReady = true;
   343→    const charId = getSafeSelectedCharacter();
   344→    this.battleChannel.sendReady(charId);
   345→
   346→    // UI 갱신: 현재 화면 정리 → 대기 화면
   347→    this.clearUI();
   348→    this.ui(this.add.text(200, 270, '✅ 준비 완료!', {
   349→      fontSize: '24px', color: '#00ff00', fontStyle: 'bold',
   350→      stroke: '#000', strokeThickness: 4,
   351→    }).setOrigin(0.5));
   352→    this.ui(this.add.text(200, 320, '상대를 기다리는 중...', {
   353→      fontSize: '16px', color: '#ffffff',
   354→      stroke: '#000', strokeThickness: 3,
   355→    }).setOrigin(0.5));
   356→
   357→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
   358→    // setInterval 사용 (Phaser 타이머는 백그라운드 탭에서 멈추므로)
   359→    this.clearReadyRetry();
   360→    this.readyRetryTimer = setInterval(() => {
   361→      if (this.countdownStarted || !this.battleChannel) {
   362→        this.clearReadyRetry();
   363→        return;
   364→      }
   365→      this.battleChannel.sendReady(charId);
   366→    }, 1500);
   367→
   368→    this.checkBothReady();
