     2→
     3→const corsHeaders = {
     4→  'Access-Control-Allow-Origin': '*',
     5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
     6→};
     7→
     8→const VALID_RESULTS = ['win', 'lose', 'disconnect'] as const;
     9→type BattleResultValue = typeof VALID_RESULTS[number];
    10→
    11→const RESULT_TO_COLUMN: Record<BattleResultValue, string> = {
    12→  win: 'wins',
    13→  lose: 'losses',
    14→  disconnect: 'disconnects',
    15→};
    16→
    17→Deno.serve(async (req: Request) => {
    18→  if (req.method === 'OPTIONS') {
    19→    return new Response('ok', { headers: corsHeaders });
    20→  }
    21→
    22→  try {
    23→    const { result } = await req.json();
    24→
    25→    // 입력 검증
    26→    if (!VALID_RESULTS.includes(result)) {
    27→      return new Response(
    28→        JSON.stringify({ error: 'Invalid result: must be win, lose, or disconnect' }),
    29→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    30→      );
    31→    }
    32→
    33→    // JWT 인증 (필수)
    34→    const authHeader = req.headers.get('Authorization');
    35→    if (!authHeader) {
    36→      return new Response(
    37→        JSON.stringify({ error: 'Missing authorization header' }),
    38→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    39→      );
    40→    }
    41→
    42→    const supabaseUser = createClient(
    43→      Deno.env.get('SUPABASE_URL') ?? '',
    44→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    45→      { global: { headers: { Authorization: authHeader } } }
    46→    );
    47→
    48→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    49→    if (authError || !user) {
    50→      return new Response(
    51→        JSON.stringify({ error: 'Unauthorized' }),
    52→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    53→      );
    54→    }
    55→
    56→    const supabaseAdmin = createClient(
    57→      Deno.env.get('SUPABASE_URL') ?? '',
    58→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    59→    );
    60→
    61→    const column = RESULT_TO_COLUMN[result as BattleResultValue];
    62→
    63→    // 원자적 upsert + rank 반환 (DB 함수)
