      }).setOrigin(0.5);
      this.leaderboardTexts.push(noData);
      return;
    }

    const startY = 165;
    const lineH = 33;

    this.leaderboardEntries.forEach((entry, index) => {
      const y = startY + index * lineH;
      const isMe = entry.userId === this.currentUserId;

      // 현재 유저 행 하이라이트
      if (isMe) {
        const highlight = this.add.rectangle(200, y, 380, 30, 0x8B6914, 0.5);
        this.leaderboardTexts.push(highlight);
      }

      // 순위 색상
      let color = '#ffffff';
      if (entry.rank === 1) color = '#FFD700';
      else if (entry.rank === 2) color = '#C0C0C0';
      else if (entry.rank === 3) color = '#CD7F32';
      else if (isMe) color = '#FFD700';

      const rankStr = `${entry.rank}`.padStart(2, ' ');
      const nameStr = entry.userName.padEnd(6, ' ');
      const winsStr = `${entry.wins + entry.disconnects}`.padStart(3, ' ');
      const lossStr = `${entry.losses}`.padStart(3, ' ');
      const rateStr = `${entry.winRate}%`.padStart(6, ' ');

      const text = this.add.text(
        200, y,
        `${rankStr}   ${nameStr}  ${winsStr} ${lossStr}  ${rateStr}`,
        {
          fontSize: '14px',
          color,
          fontFamily: 'monospace',
          stroke: '#000',
          strokeThickness: 3,
        }
      ).setOrigin(0.5);
      this.leaderboardTexts.push(text);
    });
  }
}

