     1→import { supabase } from './supabase';
     2→import { type BattleResult } from '../types/BattleTypes';
     3→
     4→export interface BattleRecordEntry {
     5→  rank: number;
     6→  userId: string;
     7→  userName: string;
     8→  wins: number;
     9→  losses: number;
    10→  disconnects: number;
    11→  totalWins: number;
    12→  winRate: number;
    13→  ratingPoints: number;
    14→  tierName: string;
    15→  tierIcon: string;
    16→}
    17→
    18→export interface SubmitBattleResultResponse {
    19→  success: boolean;
    20→  ratingPoints: number;
    21→  pointDelta: number;
    22→  wins: number;
    23→  losses: number;
    24→  disconnects: number;
    25→  winRate: number;
    26→  rank: number;
    27→  tierName: string;
    28→  tierIcon: string;
    29→}
    30→
    31→export interface BattleLeaderboardResponse {
    32→  success: boolean;
    33→  leaderboard: BattleRecordEntry[];
    34→  currentUserRank: {
    35→    rank: number;
    36→    totalWins: number;
    37→    winRate: number;
    38→    ratingPoints: number;
    39→  } | null;
    40→}
    41→
    42→/**
    43→ * 대전 결과를 서버에 제출
    44→ * opponentId: 상대 유저 UUID (RP 차이 기반 변동 계산에 사용)
    45→ */
    46→export async function submitBattleResult(
    47→  result: BattleResult,
    48→  opponentId?: string,
    49→): Promise<SubmitBattleResultResponse> {
    50→  let { data: { session } } = await supabase.auth.getSession();
    51→
    52→  if (!session) {
    53→    const { data: authData } = await supabase.auth.signInAnonymously();
    54→    session = authData.session;
    55→  }
    56→
    57→  const { data, error } = await supabase.functions.invoke('battle-result-submit', {
    58→    body: { result, opponentId },
    59→    headers: session?.access_token
    60→      ? { Authorization: `Bearer ${session.access_token}` }
    61→      : undefined,
    62→  });
    63→
    64→  if (error) {
    65→    throw new Error(error.message || 'Failed to submit battle result');
    66→  }
    67→
    68→  return data as SubmitBattleResultResponse;
    69→}
    70→
    71→/**
    72→ * 배틀 리더보드 상위 N명 조회
    73→ */
    74→export async function getBattleLeaderboard(limit: number = 20): Promise<BattleLeaderboardResponse> {
    75→  let { data: { session } } = await supabase.auth.getSession();
    76→
    77→  if (!session) {
    78→    const { data: authData } = await supabase.auth.signInAnonymously();
    79→    session = authData.session;
    80→  }
    81→
    82→  const { data, error } = await supabase.functions.invoke('battle-leaderboard-top', {
    83→    body: { limit },
    84→    headers: session?.access_token
    85→      ? { Authorization: `Bearer ${session.access_token}` }
    86→      : undefined,
    87→  });
    88→
    89→  if (error) {
    90→    throw new Error(error.message || 'Failed to fetch battle leaderboard');
    91→  }
    92→
    93→  return data as BattleLeaderboardResponse;
    94→}
