    91→        .eq('user_id', currentUserId)
    92→        .single();
    93→
    94→      if (userRecord) {
    95→        const rp: number = (userRecord as { rating_points: number }).rating_points ?? 1000;
    96→        const totalWins = (userRecord.wins as number) + (userRecord.disconnects as number);
    97→        const { data: rankResult } = await supabaseAdmin
    98→          .rpc('get_battle_rank_by_rp', { p_rp: rp });
    99→
   100→        const totalGames =
   101→          (userRecord.wins as number) +
   102→          (userRecord.losses as number) +
   103→          (userRecord.disconnects as number);
   104→        const winRate = totalGames === 0
   105→          ? 0
   106→          : Math.round(totalWins / totalGames * 1000) / 10;
   107→
   108→        currentUserRank = {
   109→          rank: Number(rankResult ?? 0) + 1,
   110→          totalWins,
   111→          winRate,
   112→          ratingPoints: rp,
   113→        };
   114→      }
   115→    }
   116→
   117→    return new Response(
   118→      JSON.stringify({
   119→        success: true,
   120→        leaderboard: entries,
   121→        currentUserRank,
   122→      }),
   123→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   124→    );
   125→  } catch (error) {
