   303→  private setupChannelListeners() {
   304→    if (!this.battleChannel) return;
   305→
   306→    // Presence join — 호스트일 때 상대 입장 UI 갱신 + 즉시 ready 전송
   307→    this.battleChannel.onPresenceJoin(() => {
   308→      if (this.isHost && !this.myReady) {
   309→        this.doSendReady();
   310→      }
   311→    });
   312→
   313→    this.battleChannel.onPresenceLeave(() => {
   314→      this.opponentReady = false;
   315→      this.ui(this.add.text(200, 420, '⚠️ 상대방이 나갔습니다', {
