   318→      }).setOrigin(0.5));
   319→    });
   320→
   321→    // READY 수신 = 상대가 확실히 존재 + 준비 완료
   322→    // Presence join보다 READY가 먼저 올 수 있으므로, 여기서도 자신의 ready를 보냄
   323→    this.battleChannel.onEvent(BattleEvent.READY, (payload: ReadyPayload) => {
   324→      this.opponentReady = true;
   325→      if (payload.userId) this.opponentUserId = payload.userId;
   326→      // 아직 내 ready를 안 보냈으면 즉시 보냄 (Presence 이벤트 누락 대비)
   327→      if (!this.myReady) {
   328→        this.doSendReady();
   329→      }
   330→      this.checkBothReady();
   331→    });
   332→
   333→    this.battleChannel.onEvent(BattleEvent.GAME_START, () => {
   334→      if (!this.countdownStarted) {
   335→        this.countdownStarted = true;
   336→        this.showCountdown();
   337→      }
   338→    });
   339→  }
