   358→
   359→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
   360→    // setInterval 사용 (Phaser 타이머는 백그라운드 탭에서 멈추므로)
   361→    this.clearReadyRetry();
