     1→export interface BattleTierDef {
     2→  name: string;
     3→  icon: string;
     4→  minRp: number;
     5→  maxRp: number;
     6→  color: string; // hex 색상 (UI 표시용)
     7→}
     8→
     9→/**
    10→ * 배틀 티어 구간 정의 (RP 오름차순)
    11→ * 신규 유저 시작 RP: 1000 (⚡ 번개손 구간 하단)
    12→ */
    13→export const BATTLE_TIERS: readonly BattleTierDef[] = [
    14→  { name: '똥뉴비',    icon: '💩', minRp: 0,    maxRp: 499,       color: '#8B4513' },
    15→  { name: '피하기꾼',  icon: '🟤', minRp: 500,  maxRp: 999,       color: '#CD7F32' },
    16→  { name: '번개손',    icon: '⚡', minRp: 1000, maxRp: 1499,      color: '#C0C0C0' },
    17→  { name: '금똥전사',  icon: '🥇', minRp: 1500, maxRp: 1999,      color: '#FFD700' },
    18→  { name: '다이아똥왕', icon: '💎', minRp: 2000, maxRp: 2499,     color: '#00BFFF' },
    19→  { name: '전설',      icon: '👑', minRp: 2500, maxRp: Infinity,  color: '#FF4500' },
    20→] as const;
    21→
    22→/** RP로 티어 인덱스 반환 (0~5) */
    23→export function getTierIndex(rp: number): number {
    24→  for (let i = BATTLE_TIERS.length - 1; i >= 0; i--) {
    25→    if (rp >= BATTLE_TIERS[i].minRp) return i;
    26→  }
    27→  return 0;
    28→}
    29→
    30→/** RP로 티어 정의 반환 */
    31→export function getBattleTier(rp: number): BattleTierDef {
    32→  return BATTLE_TIERS[getTierIndex(rp)];
    33→}
    34→
    35→/**
    36→ * 대전 결과 + 양측 RP로 포인트 변동량 계산
    37→ *
    38→ * tierDiff = 상대 티어 인덱스 - 내 티어 인덱스
    39→ * 양수: 상대가 더 높은 티어 (이기면 많이 획득, 지면 적게 잃음)
    40→ * 음수: 상대가 더 낮은 티어 (이겨도 적게 획득, 지면 많이 잃음)
    41→ */
    42→export function calcPointDelta(
    43→  result: 'win' | 'lose' | 'disconnect',
    44→  myRp: number,
    45→  opponentRp: number,
    46→): number {
    47→  if (result === 'disconnect') return 20;
    48→
    49→  const myTier = getTierIndex(myRp);
    50→  const opponentTier = getTierIndex(opponentRp);
    51→  const tierDiff = opponentTier - myTier;
    52→
    53→  if (result === 'win') {
    54→    if (tierDiff >= 2)  return 35;
    55→    if (tierDiff === 1) return 30;
    56→    if (tierDiff === 0) return 25;
    57→    if (tierDiff === -1) return 20;
    58→    return 15; // tierDiff <= -2
    59→  } else {
    60→    // lose
    61→    if (tierDiff >= 2)  return -10;
    62→    if (tierDiff === 1) return -15;
    63→    if (tierDiff === 0) return -20;
    64→    if (tierDiff === -1) return -25;
    65→    return -30; // tierDiff <= -2
    66→  }
    67→}
