     1→import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
     2→
     3→const corsHeaders = {
     4→  'Access-Control-Allow-Origin': '*',
     5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
     6→};
     7→
     8→const VALID_RESULTS = ['win', 'lose', 'disconnect'] as const;
     9→type BattleResultValue = typeof VALID_RESULTS[number];
    10→
    11→// ── 티어 계산 (battleTier.ts 로직 인라인 — Deno에서 로컬 TS 공유 불가) ──
    12→
    13→interface TierDef {
    14→  minRp: number;
    15→  maxRp: number;
    16→}
    17→
    18→const TIERS: TierDef[] = [
    19→  { minRp: 0,    maxRp: 499 },
    20→  { minRp: 500,  maxRp: 999 },
    21→  { minRp: 1000, maxRp: 1499 },
    22→  { minRp: 1500, maxRp: 1999 },
    23→  { minRp: 2000, maxRp: 2499 },
    24→  { minRp: 2500, maxRp: Infinity },
    25→];
    26→
    27→const TIER_NAMES = ['똥뉴비', '피하기꾼', '번개손', '금똥전사', '다이아똥왕', '전설'];
    28→const TIER_ICONS = ['💩', '🟤', '⚡', '🥇', '💎', '👑'];
    29→
    30→function getTierIndex(rp: number): number {
    31→  for (let i = TIERS.length - 1; i >= 0; i--) {
    32→    if (rp >= TIERS[i].minRp) return i;
    33→  }
    34→  return 0;
    35→}
    36→
    37→function calcPointDelta(
    38→  result: BattleResultValue,
    39→  myRp: number,
    40→  opponentRp: number,
    41→): number {
    42→  if (result === 'disconnect') return 20;
    43→
    44→  const tierDiff = getTierIndex(opponentRp) - getTierIndex(myRp);
    45→
    46→  if (result === 'win') {
    47→    if (tierDiff >= 2)   return 35;
    48→    if (tierDiff === 1)  return 30;
    49→    if (tierDiff === 0)  return 25;
    50→    if (tierDiff === -1) return 20;
    51→    return 15;
    52→  } else {
    53→    if (tierDiff >= 2)   return -10;
    54→    if (tierDiff === 1)  return -15;
    55→    if (tierDiff === 0)  return -20;
    56→    if (tierDiff === -1) return -25;
    57→    return -30;
    58→  }
    59→}
    60→
    61→// ── 메인 핸들러 ──
    62→
    63→Deno.serve(async (req: Request) => {
    64→  if (req.method === 'OPTIONS') {
    65→    return new Response('ok', { headers: corsHeaders });
    66→  }
    67→
    68→  try {
    69→    const { result, opponentId } = await req.json();
    70→
    71→    // 입력 검증
    72→    if (!VALID_RESULTS.includes(result)) {
    73→      return new Response(
    74→        JSON.stringify({ error: 'Invalid result: must be win, lose, or disconnect' }),
    75→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    76→      );
    77→    }
    78→
    79→    // JWT 인증 (필수)
    80→    const authHeader = req.headers.get('Authorization');
    81→    if (!authHeader) {
    82→      return new Response(
    83→        JSON.stringify({ error: 'Missing authorization header' }),
    84→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    85→      );
    86→    }
    87→
    88→    const supabaseUser = createClient(
    89→      Deno.env.get('SUPABASE_URL') ?? '',
    90→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    91→      { global: { headers: { Authorization: authHeader } } },
    92→    );
    93→
    94→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    95→    if (authError || !user) {
    96→      return new Response(
    97→        JSON.stringify({ error: 'Unauthorized' }),
    98→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    99→      );
   100→    }
   101→
   102→    const supabaseAdmin = createClient(
   103→      Deno.env.get('SUPABASE_URL') ?? '',
   104→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
   105→    );
   106→
   107→    // 내 현재 RP 조회 (없으면 신규 유저 기본값 1000)
   108→    const { data: myRecord } = await supabaseAdmin
   109→      .from('battle_records')
   110→      .select('rating_points')
   111→      .eq('user_id', user.id)
   112→      .single();
   113→    const myRp: number = (myRecord as { rating_points: number } | null)?.rating_points ?? 1000;
   114→
   115→    // 상대 RP 조회 (없으면 기본값 1000)
   116→    let opponentRp = 1000;
   117→    if (opponentId && typeof opponentId === 'string') {
   118→      const { data: oppRecord } = await supabaseAdmin
   119→        .from('battle_records')
   120→        .select('rating_points')
   121→        .eq('user_id', opponentId)
   122→        .single();
   123→      if (oppRecord) {
   124→        opponentRp = (oppRecord as { rating_points: number }).rating_points;
   125→      }
   126→    }
   127→
   128→    // RP 변동 계산
   129→    const pointDelta = calcPointDelta(result as BattleResultValue, myRp, opponentRp);
   130→
   131→    // 원자적 upsert + RP 갱신 (DB 함수)
   132→    const { data: records, error: rpcError } = await supabaseAdmin.rpc(
   133→      'submit_battle_record',
   134→      { p_user_id: user.id, p_result: result, p_point_delta: pointDelta },
   135→    );
   136→
   137→    if (rpcError || !records || records.length === 0) {
   138→      console.error('RPC error detail:', JSON.stringify(rpcError));
   139→      console.error('records:', JSON.stringify(records));
   140→      return new Response(
   141→        JSON.stringify({
   142→          error: 'Failed to update battle record',
   143→          detail: rpcError?.message ?? 'no records returned',
   144→          code: rpcError?.code,
   145→        }),
   146→        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   147→      );
   148→    }
   149→
   150→    const record = records[0];
   151→    const newRp: number = record.rating_points;
   152→    const totalGames = record.wins + record.losses + record.disconnects;
   153→    const winRate = totalGames === 0
   154→      ? 0
   155→      : Math.round((record.wins + record.disconnects) / totalGames * 1000) / 10;
   156→
   157→    const tierIdx = getTierIndex(newRp);
   158→
   159→    return new Response(
   160→      JSON.stringify({
   161→        success: true,
   162→        ratingPoints: newRp,
   163→        pointDelta,
   164→        wins: record.wins,
   165→        losses: record.losses,
   166→        disconnects: record.disconnects,
   167→        winRate,
   168→        rank: Number(record.rank),
   169→        tierName: TIER_NAMES[tierIdx],
   170→        tierIcon: TIER_ICONS[tierIdx],
   171→      }),
   172→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   173→    );
   174→  } catch (error) {
   175→    console.error('Unexpected error:', error);
   176→    return new Response(
   177→      JSON.stringify({ error: 'Internal server error' }),
   178→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   179→    );
   180→  }
   181→});
