    32→  }
    33→
    34→  // SDK가 현재 세션의 Authorization 헤더를 자동으로 포함
    35→  const { data, error } = await supabase.functions.invoke('gacha-pull', {
    36→    body: { pullType },
    37→  });
    38→
    39→  if (error) {
    40→    throw new Error(error.message || 'Failed to pull gacha');
    41→  }
    42→
