    91→  const serverIds = rows.map(r => r.character_id);
    92→  const localIds = getOwnedCharacters();
    93→  const merged = [...new Set([...serverIds, ...localIds])];
    94→  if (!merged.includes('chibi')) merged.unshift('chibi');
