    46→export async function submitBattleResult(
    47→  result: BattleResult,
    48→  opponentId?: string,
    49→): Promise<SubmitBattleResultResponse> {
    50→  let { data: { session } } = await supabase.auth.getSession();
    51→
    52→  if (!session) {
    53→    const { data: authData } = await supabase.auth.signInAnonymously();
    54→    session = authData.session;
    55→  }
    56→
    57→  const { data, error } = await supabase.functions.invoke('battle-result-submit', {
    58→    body: { result, opponentId },
    59→    headers: session?.access_token
    60→      ? { Authorization: `Bearer ${session.access_token}` }
    61→      : undefined,
    62→  });
    63→
    64→  if (error) {
    65→    throw new Error(error.message || 'Failed to submit battle result');
    66→  }
