### 권장 해결책
`BaseScene`에 헬퍼 메서드 추가:
```typescript
protected createButton(
  x: number,
  y: number,
  width: number,
  height: number,
  color: number,
  label: string,
  onPress: () => void,
  options?: { fontSize?: string; strokeColor?: number; strokeThickness?: number }
): Phaser.GameObjects.Rectangle {
  const btn = this.add.rectangle(x, y, width, height, color);
  btn.setStrokeStyle(options?.strokeThickness ?? 3, options?.strokeColor ?? 0xffffff);

  this.add.text(x, y, label, {
    fontSize: options?.fontSize ?? '20px',
    color: '#ffffff',
    fontStyle: 'bold',
  }).setOrigin(0.5);

  btn.setInteractive({ useHandCursor: true });
  btn.on('pointerover', () => btn.setAlpha(0.8));
  btn.on('pointerout', () => btn.setAlpha(1));
  btn.on('pointerdown', onPress);

  return btn;
}

// 사용처
const rematchBtn = this.createButton(200, 447, 250, 50, 0xe74c3c, '⚔️ 재대전', 
  () => this.scene.start('BattleMatchScene')
);
```

