protected createButton(
  x: number,
  y: number,
  width: number,
  height: number,
  color: number,
  label: string,
  onPress: () => void,
  options?: { fontSize?: string; strokeColor?: number; strokeThickness?: number }
): Phaser.GameObjects.Rectangle {
