toolUseResult.originalFile:
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const TIER_NAMES = ['똥뉴비', '피하기꾼', '번개손', '금똥전사', '다이아똥왕', '전설'];
const TIER_ICONS = ['💩', '🟤', '⚡', '🥇', '💎', '👑'];
const TIER_MINS  = [0, 500, 1000, 1500, 2000, 2500];

function getTierIndex(rp: number): number {
  for (let i = TIER_MINS.length - 1; i >= 0; i--) {
    if (rp >= TIER_MINS[i]) return i;
  }
  return 0;
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { limit: limitParam } = await req.json().catch(() => ({}));
    const safeLimit = Math.min(Math.max(1, parseInt(limitParam ?? '20', 10)), 100);

    // JWT에서 사용자 인증 (선택적 — 비로그인 시에도 랭킹 조회 가능)
    const authHeader = req.headers.get('Authorization');
    let currentUserId: string | null = null;

    if (authHeader) {
      const supabaseUser = createClient(
        Deno.env.get('SUPABASE_URL') ?? '',
        Deno.env.get('SUPABASE_ANON_KEY') ?? '',
        { global: { headers: { Authorization: authHeader } } },
      );
      const { data: { user } } = await supabaseUser.auth.getUser();
      currentUserId = user?.id ?? null;
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    );

    // 랭킹 뷰 조회 (rating_points DESC 정렬)
    const { data: leaderboard, error: leaderboardError } = await supabaseAdmin
      .from('battle_leaderboard_view')
      .select('user_id, rating_points, wins, losses, disconnects, win_rate, initials')
      .limit(safeLimit);

    if (leaderboardError) {
      console.error('Leaderboard query error:', leaderboardError);
      return new Response(
        JSON.stringify({ error: 'Failed to fetch leaderboard' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const entries = (leaderboard ?? []).map((entry, index) => {
      const rp: number = (entry.rating_points as number) ?? 1000;
      const tierIdx = getTierIndex(rp);
      return {
        rank: index + 1,
        userId: entry.user_id,
        userName: (entry.initials as string | null) ?? '???',
        wins: entry.wins,
        losses: entry.losses,
        disconnects: entry.disconnects,
        totalWins: (entry.wins as number) + (entry.disconnects as number),
        winRate: Number(entry.win_rate),
        ratingPoints: rp,
        tierName: TIER_NAMES[tierIdx],
        tierIcon: TIER_ICONS[tierIdx],
      };
    });

    // 현재 유저 순위 조회
    let currentUserRank: {
      rank: number;
      totalWins: number;
      winRate: number;
      ratingPoints: number;
    } | null = null;

    if (currentUserId) {
      const { data: userRecord } = await supabaseAdmin
        .from('battle_records')
        .select('wins, losses, disconnects, rating_points')
        .eq('user_id', currentUserId)
        .single();

      if (userRecord) {
        const rp: number = (userRecord as { rating_points: number }).rating_points ?? 1000;
        const totalWins = (userRecord.wins as number) + (userRecord.disconnects as number);
        const { data: rankResult } = await supabaseAdmin
          .rpc('get_battle_rank_by_rp', { p_rp: rp });

        const totalGames =
          (userRecord.wins as number) +
          (userRecord.losses as number) +
          (userRecord.disconnects as number);
        const winRate = totalGames === 0
          ? 0
          : Math.round(totalWins / totalGames * 1000) / 10;

        currentUserRank = {
          rank: Number(rankResult ?? 0) + 1,
          totalWins,
          winRate,
          ratingPoints: rp,
        };
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        leaderboard: entries,
        currentUserRank,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }
});

export interface BattleTierDef {
  name: string;
  icon: string;
  minRp: number;
  maxRp: number;
  color: string; // hex 색상 (UI 표시용)
}

/**
 * 배틀 티어 구간 정의 (RP 오름차순)
 * 신규 유저 시작 RP: 1000 (⚡ 번개손 구간 하단)
 */
export const BATTLE_TIERS: readonly BattleTierDef[] = [
  { name: '똥뉴비',    icon: '💩', minRp: 0,    maxRp: 499,       color: '#8B4513' },
  { name: '피하기꾼',  icon: '🟤', minRp: 500,  maxRp: 999,       color: '#CD7F32' },
  { name: '번개손',    icon: '⚡', minRp: 1000, maxRp: 1499,      color: '#C0C0C0' },
  { name: '금똥전사',  icon: '🥇', minRp: 1500, maxRp: 1999,      color: '#FFD700' },
  { name: '다이아똥왕', icon: '💎', minRp: 2000, maxRp: 2499,     color: '#00BFFF' },
  { name: '전설',      icon: '👑', minRp: 2500, maxRp: Infinity,  color: '#FF4500' },
] as const;

/** RP로 티어 인덱스 반환 (0~5) */
export function getTierIndex(rp: number): number {
  for (let i = BATTLE_TIERS.length - 1; i >= 0; i--) {
    if (rp >= BATTLE_TIERS[i].minRp) return i;
  }
  return 0;
}

/** RP로 티어 정의 반환 */
export function getBattleTier(rp: number): BattleTierDef {
  return BATTLE_TIERS[getTierIndex(rp)];
}

/**
 * 대전 결과 + 양측 RP로 포인트 변동량 계산
 *
 * tierDiff = 상대 티어 인덱스 - 내 티어 인덱스
 * 양수: 상대가 더 높은 티어 (이기면 많이 획득, 지면 적게 잃음)
 * 음수: 상대가 더 낮은 티어 (이겨도 적게 획득, 지면 많이 잃음)
 */
export function calcPointDelta(
  result: 'win' | 'lose' | 'disconnect',
  myRp: number,
  opponentRp: number,
): number {
  if (result === 'disconnect') return 20;

  const myTier = getTierIndex(myRp);
  const opponentTier = getTierIndex(opponentRp);
  const tierDiff = opponentTier - myTier;

  if (result === 'win') {
    if (tierDiff >= 2)  return 35;
    if (tierDiff === 1) return 30;
    if (tierDiff === 0) return 25;
    if (tierDiff === -1) return 20;
    return 15; // tierDiff <= -2
  } else {
    // lose
    if (tierDiff >= 2)  return -10;
    if (tierDiff === 1) return -15;
    if (tierDiff === 0) return -20;
    if (tierDiff === -1) return -25;
    return -30; // tierDiff <= -2
  }
}
